import React from 'react';
import { connect } from 'react-redux';
import { Card, Row, Col } from 'reactstrap';

import { fetchAllNoticeBoardService, saveNoticeBoardService, deleteNoticeBoardService } from 'actions/admin/students';
import NoticeBoardFormModal from './components/NoticeBoardFormModal.jsx';
import { formResMessage, getGlobalSchoolUtils } from '../../../../utils/commonFunc.js';
import { store } from '../../../../index.js';
import { showToast } from '../../../../actions/admin/auth.js';
import { hasMorePages } from '../../../../utils/paging.js';
import CustomButton from '../../../../components/CustomButton.jsx';

// Card
import ConfirmModal from 'views/admin/Common/ConfirmModal.jsx';
import { LoadingCard } from 'views/admin/Common/Loader.jsx';
import AnnouncementList from 'views/admin/Common/AnnouncementList.jsx';

const GridContainer = ({ noticeBoardList, deleteNoticeBoard, highlightId, hasMore, loadingMore, onLoadMore }) => (
  <AnnouncementList
    hasMore={hasMore}
    loadingMore={loadingMore}
    onLoadMore={onLoadMore}
    idPrefix="notice-board"
    contentType="NOTICE_BOARD"
    highlightId={highlightId}
    onDelete={deleteNoticeBoard}
    items={noticeBoardList.map(item => ({
      id: item.noticeBoardId,
      title: item.subject,
      date: item.creationDateTime,
      content: item.content,
    }))}
  />
);

const PAGE_SIZE = 20;

class NoticeBoardPage extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      isModalOpen: false,
      isStatusModalOpen: false,
      schoolId: 0,
      confirmModalOpen: false,
      noticeBoardId: null,
      page: 1,
      hasMore: false,
      loadingMore: false,
    };
  }

  componentDidMount() {
    const globalSchool = getGlobalSchoolUtils();
    if (globalSchool) {
      this.setState({ schoolId: globalSchool.schoolId }, () => {
        this.fetchAllNoticeBoards(true);
      });
    }
  }

  isLoading = (name, value) => this.setState({ [name]: value });

  // Newest first, no date filter. Page 1 replaces the list, "Load more" adds the next page. When a dashboard card pointed
  // at one notice, pages are read (up to a few) until that one is on screen.
  fetchAllNoticeBoards = async (reset = false) => {
    const { schoolId, page: currentPage } = this.state;
    const { highlightId } = this.props;
    const page = reset ? 1 : currentPage + 1;
    if (reset) this.props.isLoading('noticeFetching', true);
    else this.setState({ loadingMore: true });
    const res = await this.props.fetchAllNoticeBoards({
      schoolId,
      token: this.props.loggedUserToken,
      page,
      size: PAGE_SIZE,
    });
    this.setState({ page, hasMore: hasMorePages(res?.data, page, PAGE_SIZE), loadingMore: false });
    if (reset) this.props.isLoading('noticeFetching', false);
    const found = (this.props.noticeBoardList || []).some(n => String(n.noticeBoardId) === String(highlightId));
    if (reset && highlightId && !found && hasMorePages(res?.data, page, PAGE_SIZE) && page < 5) {
      this.fetchAllNoticeBoards(false);
    }
  };

  showWarning = (message, type) => {
    store.dispatch(showToast(message, type));
  };

  // NoticeBoard section ///
  formModalOpen = () => {
    this.setState({ isModalOpen: true });
  };

  formModalClose = () => {
    this.setState({
      isModalOpen: false,
      isStatusModalOpen: false,
      confirmModalOpen: false,
      noticeBoardId: null,
    });
  };

  saveNoticeBoard = data => {
    const postData = {
      ...data,
      school: { schoolId: this.state.schoolId },
    };
    return this.props.saveNoticeBoard({ postData, token: this.props.loggedUserToken }).then(() => {
      this.fetchAllNoticeBoards(true);
    });
  };

  noticeBoardUpdateSuccess = actionParam => {
    this.formModalClose();
    this.showWarning(
      actionParam === 'add' ? 'NoticeBoard added successfully' : 'NoticeBoard Updated successfully',
      'success'
    );
  };

  deleteNoticeBoard = noticeBoardId => {
    this.formModalClose();
    return this.props
      .deleteNoticeBoard({ noticeBoardId, token: this.props.loggedUserToken })
      .then(() => {
        this.fetchAllNoticeBoards(true);
      })
      .catch(err => {
        this.showWarning(formResMessage(err), 'error');
      });
  };

  deleteConfirmModalOpen = async noticeBoardId => {
    this.setState({ confirmModalOpen: true, noticeBoardId });
  };

  deleteConfirm = () => this.deleteNoticeBoard(this.state.noticeBoardId);

  render() {
    const { isModalOpen, confirmModalOpen, hasMore, loadingMore } = this.state;
    const { noticeBoardList, noticeFetching } = this.props;
    const noDataFoundDiv = (
      <Card className="text-center">
        <span colSpan="5" style={{ padding: 30, fontWeight: 'bold' }}>
          NO DATA FOUND
        </span>
      </Card>
    );
    return (
      <div className="content">
        <Row>
          <Col>
            <CustomButton
              className="mb-3"
              style={{ float: 'right' }}
              onClick={this.formModalOpen}
              name="Add NoticeBoard"
            />
          </Col>
        </Row>
        {noticeFetching ? (
          <LoadingCard />
        ) : noticeBoardList?.length ? (
          <>
            <GridContainer
              noticeBoardList={noticeBoardList}
              deleteNoticeBoard={this.deleteConfirmModalOpen}
              highlightId={this.props.highlightId}
              hasMore={hasMore}
              loadingMore={loadingMore}
              onLoadMore={() => this.fetchAllNoticeBoards(false)}
            />
          </>
        ) : (
          <Row>
            <Col md={12}>{noDataFoundDiv}</Col>
          </Row>
        )}
        <NoticeBoardFormModal
          isModalOpen={isModalOpen}
          formModalCloseProp={this.formModalClose}
          saveNoticeBoard={this.saveNoticeBoard}
          noticeBoardUpdateSuccess={this.noticeBoardUpdateSuccess}
        />
        <ConfirmModal
          confirmModalOpen={confirmModalOpen}
          deleteConfirm={this.deleteConfirm}
          deleteCancel={this.formModalClose}
        />
      </div>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserId: state.auth.loggedUserId,
    loggedUserToken: state.auth.loggedUserToken,
    noticeBoardList: state.students.noticeBoardList,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    fetchAllNoticeBoards: data => dispatch(fetchAllNoticeBoardService(data)),
    saveNoticeBoard: data => dispatch(saveNoticeBoardService(data)),
    deleteNoticeBoard: data => dispatch(deleteNoticeBoardService(data)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(NoticeBoardPage);
