// Whether a Spring page response has a page after `page` (1-based). Older backends send `last`; newer ones send
// `page: { number, totalPages }` instead and no `last`; without either, a full page is taken to mean there may be more.
export const hasMorePages = (data, page, size) => {
  if (!data) return false;
  if (typeof data.last === 'boolean') return !data.last;
  if (data.page && typeof data.page.totalPages === 'number') return page < data.page.totalPages;
  if (typeof data.totalPages === 'number') return page < data.totalPages;
  return (data.content?.length || 0) >= size;
};
