import React from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col, Input, Label, FormGroup } from 'reactstrap';
import { formResMessage } from 'utils/commonFunc';
import Validator from 'validator';
import CustomButton from '../../../../../components/CustomButton';

const stateObj = {
  data: {
    content: '',
    subject: '',
  },
  errors: {},
  loading: false,
};

class NoticeBoardFormModal extends React.Component {
  state = stateObj;

  handleChange = e =>
    this.setState({
      data: { ...this.state.data, [e.currentTarget.name]: `${e.currentTarget.value}` },
    });

  handleSubmit = e => {
    e.preventDefault();
    const { data } = this.state;
    const errors = this.validate(data);
    this.setState({ errors });
    if (Object.keys(errors).length === 0) {
      this.setState({ loading: true });
      // if(data.noticeBoardId) {
      //     this.props.updateNoticeBoard(data)
      //     .then(() => {
      //       this.stateReset();
      //       this.props.noticeBoardUpdateSuccess('update');
      //     })
      //     .catch(err =>  this.setError(err));
      // } else {
      return this.props
        .saveNoticeBoard(data)
        .then(() => {
          this.stateReset();
          this.props.noticeBoardUpdateSuccess('add');
        })
        .catch(err => {
          this.setError(err);
        });
      // }
    }
  };

  setError = err => {
    this.setState(prevState => ({
      ...prevState,
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    }));
  };

  stateReset = () => {
    this.setState(stateObj);
  };

  formModalClose = () => {
    this.stateReset();
    this.props.formModalCloseProp();
  };

  validate = data => {
    const errors = {};

    if (Validator.isEmpty(data.subject.toString().trim())) {
      errors.subject = 'Title cannot be empty';
    }

    if (Validator.isEmpty(data.content)) {
      errors.content = 'Content cannot be empty';
    }

    return errors;
  };

  render() {
    const { isModalOpen } = this.props;
    const { data, errors, loading } = this.state;
    const thisData = (
      <Modal size="lg" isOpen={isModalOpen}>
        <form onSubmit={this.handleSubmit}>
          <ModalHeader>{data.noticeBoardId ? 'UPDATE NOTICE BOARD' : 'ADD NOTICE BOARD'}</ModalHeader>
          <ModalBody>
            {errors.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
            <div className="content">
              <div className="container-fluid">
                <Row>
                  <Col sm={12}>
                    <FormGroup>
                      <Label htmlFor="">
                        Title<sup> *</sup>
                      </Label>
                      <Input
                        type="text"
                        name="subject"
                        onChange={this.handleChange}
                        value={data.title}
                        placeholder="Enter here..."
                        maxLength="50"
                      />
                      {errors.subject && <span className="err-msg">{errors.subject}</span>}
                    </FormGroup>
                  </Col>
                </Row>
                <Row>
                  <Col sm={12}>
                    <FormGroup>
                      <Label htmlFor="">
                        Content<sup> *</sup>
                      </Label>
                      <Input
                        type="textarea"
                        name="content"
                        onChange={this.handleChange}
                        value={data.content}
                        placeholder="Enter here..."
                        maxLength="5000"
                      />
                      {errors.content && <span className="err-msg">{errors.content}</span>}
                    </FormGroup>
                  </Col>
                </Row>
              </div>
            </div>
          </ModalBody>
          <ModalFooter>
            <CustomButton type="submit" disabled={loading} loading={loading} />
            <CustomButton
              className="ml-2"
              type="button"
              color="default"
              disabled={loading}
              onClick={this.formModalClose}
              name="Cancel"
            />
          </ModalFooter>
        </form>
      </Modal>
    );
    return <div>{thisData}</div>;
  }
}

export default NoticeBoardFormModal;
