import { Button } from '@material-ui/core';
import React from 'react';
import { Row, Col } from 'reactstrap';
import { isMobileView } from '../../../index';
import RefreshIcon from '@material-ui/icons/Refresh';
import CommonTooltip from '../Common/CommonTooltip';
import colors from 'config/colors.js';

const SubTabs = ({
  className = '',
  subTabs = [],
  subActive,
  tabToggle,
  disabled = false,
  showRefresh = false,
  refreshData = undefined,
}) => {
  if (!subTabs.length) {
    return null;
  }
  return (
    <div className={className}>
      <Row style={{ marginLeft: 1, marginRight: 1, alignItems: 'center' }}>
        <Col style={{ paddingLeft: 0 }}>
          {/* a segmented switch: one soft track, the chosen option lifted onto a white pill */}
          <div
            role="tablist"
            style={{
              display: 'inline-flex',
              maxWidth: '100%',
              padding: 3,
              borderRadius: 22,
              background: colors.sidebarActiveItemBg,
            }}>
            {subTabs.map((item, i) => {
              const selected = subActive === i;
              return (
                <button
                  key={i}
                  type="button"
                  role="tab"
                  aria-selected={selected}
                  onClick={() => !disabled && tabToggle(i)}
                  style={{
                    border: 0,
                    cursor: disabled ? 'default' : 'pointer',
                    padding: isMobileView ? '6px 14px' : '7px 22px',
                    borderRadius: 18,
                    fontSize: 13.5,
                    fontWeight: 'bold',
                    whiteSpace: 'nowrap',
                    color: selected ? colors.accent : colors.accentDark,
                    opacity: selected ? 1 : 0.75,
                    background: selected ? '#fff' : 'transparent',
                    boxShadow: selected ? '0 1px 4px rgba(91,21,132,0.25)' : 'none',
                    transition: 'background .15s, box-shadow .15s',
                  }}>
                  {item.tabName}
                </button>
              );
            })}
          </div>
        </Col>
        {showRefresh && (
          <div style={{ float: 'right' }}>
            <CommonTooltip placement="top" content="Refresh">
              <Button color="secondary" style={{ padding: 0 }} onClick={refreshData}>
                <RefreshIcon />
              </Button>
            </CommonTooltip>
          </div>
        )}
      </Row>
    </div>
  );
};

export default SubTabs;
