import React from 'react';
import { connect } from 'react-redux';
import { withRouter } from 'react-router-dom';
import { Row, Col, FormGroup, Label } from 'reactstrap';
import moment from 'moment';
import DatePicker from 'react-datepicker';
import { calActivityTableHead, otherActivityHead } from 'variables/general';

import {
  fetchAllCalendarActivityService,
  saveCalendarActivityService,
  deleteCalendarActivityService,
  fetchAllOtherActivitiesService,
  saveOtherActivityService,
  deleteOtherActivityService,
} from 'actions/admin/schools';
import Select from 'react-select';
import CalendarFormModal from './components/ActivityFormModal.jsx';
import {
  formResMessage,
  getCurrentYearBatchUtils,
  getGlobalCurrentBatchUtils,
  getGlobalSchoolUtils,
} from '../../../../utils/commonFunc.js';
import { store } from '../../../../index.js';
import { showToast } from '../../../../actions/admin/auth.js';
import { fetchCurrentBatchByYearService } from '../../../../actions/admin/batches.js';

import ListDropDown from '../../Common/ListDropDown.jsx';
import OtherActivityFormModal from './components/OtherActivityFormModal.jsx';
import CustomButton from '../../../../components/CustomButton.jsx';
import SubTabs from '../SubTabs.jsx';
import MuiTable from 'views/admin/Common/MuiTable.jsx';

const subTabList = [
  { tabName: `Main activities`, index: 0 },
  { tabName: `School features`, index: 1 },
];

export const activityTypes = [
  { value: 'EVENT', label: 'EVENT' },
  { value: 'HOLIDAY', label: 'HOLIDAY' },
  { value: 'MEETING', label: 'MEETING' },
  // { value: "EXAM", label: "EXAM" },
];

class CalendarPage extends React.Component {
  constructor(props) {
    super(props);
    // A dashboard event/holiday card links here with ?type=HOLIDAY&date=YYYY-MM-DD to open that list and year.
    const params = new URLSearchParams(props.location?.search);
    const linkedType = activityTypes.find(dto => dto.value === params.get('type'))?.value;
    const linkedDate = params.get('date') && moment(params.get('date'), 'YYYY-MM-DD', true);
    this.hasLink = !!linkedType || !!linkedDate?.isValid();
    this.state = {
      subActive: 0,
      activityType: linkedType || 'EVENT',
      selectedDate: linkedDate?.isValid() ? linkedDate.toDate() : new Date(),
      selectedDay: moment().format('ddd').toUpperCase(),
      isModalOpen: false,
      confirmModalOpen: false,
      isStatusModalOpen: false,
      schoolId: 0,
      isOtherActivityModalOpen: false,
    };
  }

  componentDidMount() {
    const globalSchool = getGlobalSchoolUtils();
    if (globalSchool) {
      this.setState({ schoolId: globalSchool.schoolId }, () => {
        this.fetchAllCActivities(this.hasLink);
        this.fetchAllOtherActivities();
      });
    }

    const { batchId } = getGlobalCurrentBatchUtils();
    if (!batchId) {
      this.fetchCurrentBatch();
    }
  }

  fetchCurrentBatch = () => {
    const { startYear, endYear } = getCurrentYearBatchUtils();
    const globalSchool = getGlobalSchoolUtils();
    const { batchId } = getGlobalCurrentBatchUtils();
    if (!batchId && globalSchool?.schoolId) {
      store.dispatch(
        fetchCurrentBatchByYearService({
          token: this.props.loggedUserToken,
          schoolId: globalSchool.schoolId,
          startYear,
          endYear,
        })
      );
    }
  };

  fetchAllCActivities = refetchAgain => {
    if (!this.props.calendarActivities?.length || refetchAgain) {
      this.props.fetchAllCalendarActivity({
        activityType: this.state.activityType,
        year: moment(this.state.selectedDate).format('YYYY'),
        token: this.props.loggedUserToken,
      });
    }
  };

  fetchAllOtherActivities = refetchAgain => {
    if (!this.props.otherActivities?.length || refetchAgain) {
      this.props.fetchAllOtherActivities({
        schoolId: this.state.schoolId,
        token: this.props.loggedUserToken,
      });
    }
  };

  showWarning = (message, type) => {
    this.setState({ confirmModalOpen: false });
    store.dispatch(showToast(message, type));
  };

  handleDateChange = date => {
    this.setState(
      {
        selectedDate: date,
      },
      () => {
        this.fetchAllCActivities(true);
      }
    );
  };

  handleTypeChange = val => {
    this.setState(
      {
        activityType: val.value,
      },
      () => {
        this.fetchAllCActivities(true);
      }
    );
  };

  formModalOpen = () => {
    this.setState({ isModalOpen: true });
  };

  formModalClose = () => {
    this.setState({
      isModalOpen: false,
      confirmModalOpen: false,
      isStatusModalOpen: false,
      isOtherActivityModalOpen: false,
    });
  };

  saveCalendarActivity = data => {
    const postData = {
      ...data,
      currentYear: moment(data.startDateTime).format('YYYY'),
      school: {
        schoolId: this.state.schoolId,
      },
    };
    return this.props
      .saveCalendarActivity({
        postData,
        token: this.props.loggedUserToken,
      })
      .then(() => {
        // this.fetchAllCActivities(true);
      })
      .catch(err => {
        console.error(err.response);
      });
  };

  calendarActivityUpdateSuccess = actionParam => {
    this.setState({
      isModalOpen: false,
      isOtherActivityModalOpen: false,
    });
    this.showWarning(
      actionParam === 'add' ? 'Calendar activity added successfully' : 'Calendar activity Updated successfully',
      'success'
    );
    this.fetchAllCActivities(true);
  };

  deleteCalendarActivity = calendatId => {
    return this.props
      .deleteCalendarActivity({
        calendatId,
        token: this.props.loggedUserToken,
      })
      .then(() => {
        this.fetchAllCActivities(true);
      })
      .catch(err => {
        this.showWarning(formResMessage(err), 'error');
      });
  };

  updateActivity = activityType => {
    this.setState(prevState => ({
      ...prevState,
      activityType,
    }));
  };

  otherActivityFormModalOpen = () => {
    this.setState({
      isOtherActivityModalOpen: true,
    });
  };

  saveOtherActivity = data => {
    data.schoolId = this.state.schoolId;
    return this.props.saveOtherActivity({
      postData: data,
      schoolId: this.state.schoolId,
      token: this.props.loggedUserToken,
    });
  };

  otherActivityUpdateSuccess = () => {
    this.setState({
      isModalOpen: false,
      isOtherActivityModalOpen: false,
    });
    this.showWarning('Activity saved successfully', 'success');
    this.fetchAllOtherActivities(true);
  };

  deleteOtherActivity = async extracurricularId => {
    await this.props.deleteOtherActivity({
      extracurricularId,
      token: this.props.loggedUserToken,
    });
    this.fetchAllOtherActivities(true);
  };

  handleSubTabChange = tab => {
    if (tab !== this.state.subActive) {
      this.setState(prevState => ({ ...prevState, subActive: tab }));
      if (tab === 0) {
        this.fetchAllCActivities();
      } else {
        this.fetchAllOtherActivities();
      }
    }
  };

  render() {
    const { subActive, selectedDate, isModalOpen, activityType, isOtherActivityModalOpen } = this.state;
    const { calendarActivities, otherActivities } = this.props;

    const getList = () => {
      return calendarActivities
        .filter(fData => fData.activityType === activityType)
        .map(calActivityItem => {
          return {
            title: calActivityItem.title,
            startDateTime: moment(calActivityItem.startDateTime).format('MMM DD, YYYY'),
            endDateTime: moment(calActivityItem.endDateTime).format('MMM DD, YYYY'),
            activityType: calActivityItem.activityType,
            description: calActivityItem.description,
            actionItem: (
              <ListDropDown
                actionList={['delete']}
                item={calActivityItem}
                deleteItem={() => {
                  this.deleteCalendarActivity(calActivityItem.calendatId);
                }}
              />
            ),
          };
        });
    };
    const tableData = (
      <MuiTable
        tableHeaders={calActivityTableHead}
        tableBodyData={{
          content: calendarActivities.filter(fData => fData.activityType === activityType)?.length ? getList() : [],
        }}
        bodyColumns={['title', 'startDateTime', 'endDateTime', 'activityType', 'description', 'actionItem']}
        dropDownActions={['edit', 'delete']}
        idName="calendatId"
        hidePagination={true}
        cellPadding={{ paddingTop: 8, paddingBottom: 8 }}
      />
    );
    const activitiesDiv = (
      <>
        <Row>
          <Col md={3}>
            <FormGroup className="customDatePickerWidth">
              <Label htmlFor="">
                <strong>
                  View by Year<sup> *</sup>{' '}
                </strong>
              </Label>
              <br />
              <DatePicker
                className="form-control"
                selected={new Date(selectedDate)}
                onChange={date => this.handleDateChange(date)}
                showYearPicker
                dateFormat="yyyy"
                yearItemNumber={9}
                dropdownMode="select"
              />
            </FormGroup>
          </Col>
          <Col md={3} className="ml-n3">
            <FormGroup>
              <Label htmlFor="">
                <strong>
                  View by Activity type<sup> *</sup>{' '}
                </strong>
              </Label>
              <br />
              <Select
                onChange={val => this.handleTypeChange(val)}
                options={activityTypes}
                value={activityTypes.find(dt => dt.value === activityType)}
              />
            </FormGroup>
          </Col>
          <Col md={6} className="ml-3">
            <CustomButton className="mt-4" style={{ float: 'right' }} onClick={this.formModalOpen} name="Add" />
          </Col>
        </Row>
        {tableData}
      </>
    );
    const getOtherList = () => {
      return otherActivities.map(activity => {
        return {
          extraCurricularName: activity.extraCurricularName,
          category: activity.category,
          description: activity.description,
          actionItem: (
            <ListDropDown
              actionList={['delete']}
              item={activity}
              deleteItem={() => this.deleteOtherActivity(activity.extracurricularId)}
            />
          ),
        };
      });
    };
    const otherTableData = (
      <MuiTable
        tableHeaders={otherActivityHead}
        tableBodyData={{
          content: otherActivities?.length ? getOtherList() : [],
        }}
        bodyColumns={['extraCurricularName', 'category', 'description', 'actionItem']}
        idName="extracurricularId"
        hidePagination={true}
        cellPadding={{ paddingTop: 8, paddingBottom: 8 }}
      />
    );
    const otherActivitiesDiv = (
      <>
        <Row>
          <Col md={12}>
            <CustomButton
              className="mb-3"
              style={{ float: 'right' }}
              onClick={this.otherActivityFormModalOpen}
              name="Add"
            />
          </Col>
        </Row>
        {otherTableData}
      </>
    );

    return (
      <div className="content">
        <SubTabs
          className="mb-3"
          subTabs={subTabList}
          subActive={subActive}
          tabToggle={tab => this.handleSubTabChange(tab)}
        />
        {subActive === 0 && activitiesDiv}
        {subActive === 1 && otherActivitiesDiv}
        <CalendarFormModal
          isModalOpen={isModalOpen}
          formModalCloseProp={this.formModalClose}
          saveCalendarActivity={this.saveCalendarActivity}
          calendarActivityUpdateSuccess={this.calendarActivityUpdateSuccess}
          activityType={activityType}
          updateActivity={this.updateActivity}
        />
        <OtherActivityFormModal
          isOtherActivityModalOpen={isOtherActivityModalOpen}
          formModalCloseProp={this.formModalClose}
          saveOtherActivity={this.saveOtherActivity}
          otherActivityUpdateSuccess={this.otherActivityUpdateSuccess}
        />
      </div>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserId: state.auth.loggedUserId,
    loggedUserToken: state.auth.loggedUserToken,
    subjects: state.subjects.subjectList,
    calActivityList: state.students.calActivityList,
    studentsCalendarStatusList: state.students.studentsCalendarStatusList,
    calendarActivities: state.schools.calendarActivities,
    courses: state.courses.courseList,
    // Time slots
    otherActivities: state.schools.otherActivities,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    fetchAllCalendarActivity: data => dispatch(fetchAllCalendarActivityService(data)),
    saveCalendarActivity: data => dispatch(saveCalendarActivityService(data)),
    deleteCalendarActivity: data => dispatch(deleteCalendarActivityService(data)),

    // Other activities
    fetchAllOtherActivities: data => dispatch(fetchAllOtherActivitiesService(data)),
    saveOtherActivity: data => dispatch(saveOtherActivityService(data)),
    deleteOtherActivity: data => dispatch(deleteOtherActivityService(data)),
  };
};

export default withRouter(connect(mapStateToProps, mapDispatchToProps)(CalendarPage));
