/* eslint-disable no-unused-vars */
import React, { useEffect } from 'react';
import { connect } from 'react-redux';
import { withRouter } from 'react-router-dom';
import { Card, Row, Col } from 'reactstrap';
import moment from 'moment';

import {
  fetchAllCircularService,
  saveCircularService,
  deleteCircularService,
  fetchAllNoticeBoardService,
} from 'actions/admin/students';
import CircularFormModal from './components/CircularFormModal.jsx';
import { formResMessage, getGlobalSchoolUtils } from '../../../../utils/commonFunc.js';
import { store } from '../../../../index.js';
import { showToast } from '../../../../actions/admin/auth.js';
import { hasMorePages } from '../../../../utils/paging.js';
import CustomButton from '../../../../components/CustomButton.jsx';
import SubTabs from '../SubTabs.jsx';
import NoticeBoardPage from '../NoticeBoard/NoticeBoardPage.jsx';

// Card
import ConfirmModal from 'views/admin/Common/ConfirmModal.jsx';
import { LoadingCard } from 'views/admin/Common/Loader.jsx';
import AnnouncementList from 'views/admin/Common/AnnouncementList.jsx';

const GridContainer = ({ circularList, deleteCircular, highlightId, hasMore, loadingMore, onLoadMore }) => (
  <AnnouncementList
    hasMore={hasMore}
    loadingMore={loadingMore}
    onLoadMore={onLoadMore}
    idPrefix="circular"
    contentType="CIRCULAR"
    highlightId={highlightId}
    onDelete={deleteCircular}
    items={circularList.map(item => ({
      id: item.circularId,
      title: item.subject,
      date: item.creationDateTime,
      content: item.content,
    }))}
  />
);

const subTabList = [
  { tabName: 'Circular', index: 0 },
  { tabName: 'Notice board', index: 1 },
];

const PAGE_SIZE = 20;

class CircularPage extends React.Component {
  constructor(props) {
    super(props);
    // A dashboard card links here with ?sub=noticeboard&circularId=/noticeBoardId= so the item it showed is the one
    // that is highlighted. The list itself is always newest first, with no date filter.
    const params = new URLSearchParams(props.location?.search);
    this.state = {
      isModalOpen: false,
      isStatusModalOpen: false,
      schoolId: 0,
      // `mode` is set when circulars or the notice board have their own sidebar page; without it both share one page.
      subActive:
        props.mode === 'noticeboard' ? 1 : props.mode === 'circular' ? 0 : params.get('sub') === 'noticeboard' ? 1 : 0,
      highlightCircularId: params.get('circularId'),
      highlightNoticeBoardId: params.get('noticeBoardId'),
      confirmModalOpen: false,
      circularId: null,
      circularFetching: false,
      noticeFetching: false,
      circularPage: 1,
      circularHasMore: false,
      circularLoadingMore: false,
    };
  }

  componentDidMount() {
    const globalSchool = getGlobalSchoolUtils();
    if (globalSchool) {
      this.setState({ schoolId: globalSchool.schoolId }, () => {
        if (this.props.mode !== 'noticeboard') this.fetchAllCirculars(true);
      });
    }
  }

  isLoading = (name, value) => this.setState({ [name]: value });

  // Page 1 replaces the list, "Load more" adds the next page. When a dashboard card pointed at one circular, pages are read
  // (up to a few) until that one is on screen.
  fetchAllCirculars = async (reset = false) => {
    const { schoolId, circularPage, highlightCircularId } = this.state;
    const page = reset ? 1 : circularPage + 1;
    this.isLoading(reset ? 'circularFetching' : 'circularLoadingMore', true);
    const res = await this.props.fetchAllCirculars({
      schoolId,
      token: this.props.loggedUserToken,
      page,
      size: PAGE_SIZE,
    });
    this.setState({ circularPage: page, circularHasMore: hasMorePages(res?.data, page, PAGE_SIZE) });
    this.isLoading(reset ? 'circularFetching' : 'circularLoadingMore', false);
    const found = (this.props.circularList || []).some(c => String(c.circularId) === String(highlightCircularId));
    if (reset && highlightCircularId && !found && hasMorePages(res?.data, page, PAGE_SIZE) && page < 5) {
      this.fetchAllCirculars(false);
    }
  };

  showWarning = (message, type) => {
    store.dispatch(showToast(message, type));
  };

  formModalOpen = () => {
    this.setState({ isModalOpen: true });
  };

  formModalClose = () => {
    this.setState({
      isModalOpen: false,
      isStatusModalOpen: false,
      confirmModalOpen: false,
      circularId: null,
    });
  };

  saveCircular = data => {
    const postData = {
      ...data,
      school: { schoolId: this.state.schoolId },
    };
    return this.props
      .saveCircular({ postData, token: this.props.loggedUserToken })
      .then(() => {
        this.fetchAllCirculars(true);
      })
      .catch(err => {
        console.error(err.response);
      });
  };

  circularUpdateSuccess = actionParam => {
    this.formModalClose();
    this.showWarning(
      actionParam === 'add' ? 'Circular added successfully' : 'Circular Updated successfully',
      'success'
    );
  };

  deleteCircular = circularId => {
    this.formModalClose();
    return this.props
      .deleteCircular({ circularId, token: this.props.loggedUserToken })
      .then(() => {
        this.fetchAllCirculars(true);
      })
      .catch(err => {
        this.showWarning(formResMessage(err), 'error');
      });
  };

  handleSubTabChange = tab => {
    if (tab !== this.state.subActive) {
      this.setState(prevState => ({ ...prevState, subActive: tab }));
      if (tab === 0) {
        this.fetchAllCirculars(true);
      }
    }
  };

  deleteConfirmModalOpen = async circularId => {
    this.setState({ confirmModalOpen: true, circularId });
  };

  deleteConfirm = () => this.deleteCircular(this.state.circularId);

  refreshData = async () => {
    this.fetchAllCirculars(true);
    this.isLoading('noticeFetching', true);
    await this.props.fetchAllNoticeBoards({
      schoolId: this.state.schoolId,
      token: this.props.loggedUserToken,
      page: 1,
      size: PAGE_SIZE,
    });
    this.isLoading('noticeFetching', false);
  };

  render() {
    const {
      subActive,
      isModalOpen,
      confirmModalOpen,
      circularFetching,
      noticeFetching,
      highlightCircularId,
      highlightNoticeBoardId,
      circularHasMore,
      circularLoadingMore,
    } = this.state;
    const { circularList } = this.props;

    const noDataFoundDiv = (
      <Card className="text-center">
        <span colSpan="5" style={{ padding: 30, fontWeight: 'bold' }}>
          NO DATA FOUND
        </span>
      </Card>
    );

    const circularComp = (
      <>
        <Row>
          <Col>
            <CustomButton
              className="mb-3"
              style={{ float: 'right' }}
              onClick={this.formModalOpen}
              name="Add Circular"
            />
          </Col>
        </Row>
        {circularFetching ? (
          <LoadingCard />
        ) : circularList?.length ? (
          <>
            <GridContainer
              circularList={circularList}
              deleteCircular={this.deleteConfirmModalOpen}
              highlightId={highlightCircularId}
              hasMore={circularHasMore}
              loadingMore={circularLoadingMore}
              onLoadMore={() => this.fetchAllCirculars(false)}
            />
          </>
        ) : (
          <Row>
            <Col md={12}>{noDataFoundDiv}</Col>
          </Row>
        )}
      </>
    );
    return (
      <div className="content">
        {!this.props.mode && (
          <SubTabs
            className="mb-3"
            subTabs={subTabList}
            subActive={subActive}
            tabToggle={tab => this.handleSubTabChange(tab)}
            showRefresh={true}
            refreshData={this.refreshData}
          />
        )}
        {subActive === 0 && circularComp}
        {subActive === 1 && (
          <NoticeBoardPage
            isLoading={this.isLoading}
            noticeFetching={noticeFetching}
            highlightId={highlightNoticeBoardId}
          />
        )}
        <CircularFormModal
          isModalOpen={isModalOpen}
          formModalCloseProp={this.formModalClose}
          saveCircular={this.saveCircular}
          circularUpdateSuccess={this.circularUpdateSuccess}
        />
        <ConfirmModal
          confirmModalOpen={confirmModalOpen}
          deleteConfirm={this.deleteConfirm}
          deleteCancel={this.formModalClose}
        />
      </div>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserId: state.auth.loggedUserId,
    loggedUserToken: state.auth.loggedUserToken,
    circularList: state.students.circularList,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    fetchAllCirculars: data => dispatch(fetchAllCircularService(data)),
    saveCircular: data => dispatch(saveCircularService(data)),
    deleteCircular: data => dispatch(deleteCircularService(data)),
    fetchAllNoticeBoards: data => dispatch(fetchAllNoticeBoardService(data)),
  };
};

export default withRouter(connect(mapStateToProps, mapDispatchToProps)(CircularPage));
