import React from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Input, Label, FormGroup } from 'reactstrap';
import Validator from 'validator';
import Select from 'react-select';
import CustomButton from '../../../../../components/CustomButton';
import { formResMessage } from 'utils/commonFunc';

export const activityCategories = [
  { label: 'Self defence', value: 'SELF_DEFENCE' },
  { label: 'Sports', value: 'SPORTS' },
  { label: 'Agriculture', value: 'AGRI' },
  { label: 'Music', value: 'MUSIC' },
  { label: 'Yoga', value: 'YOGA' },
  { label: 'Art', value: 'ART' },
];

const stateObj = {
  data: {
    category: '',
    description: '',
    extraCurricularName: '',
  },
  errors: {},
  loading: false,
};

class OtherActivityFormModal extends React.Component {
  state = stateObj;

  handleChange = e => {
    this.setState({
      data: { ...this.state.data, [e.currentTarget.name]: e.currentTarget.value },
    });
  };

  handleCategoryChange = val => {
    this.setState(prevState => ({
      data: {
        ...prevState.data,
        category: val.value,
      },
    }));
  };

  handleSubmit = e => {
    e.preventDefault();
    const { data } = this.state;
    const errors = this.validate(data);
    this.setState({ errors });
    if (!Object.keys(errors).length) {
      this.setState({ loading: true });
      return this.props
        .saveOtherActivity(data)
        .then(() => {
          this.stateReset();
          this.props.otherActivityUpdateSuccess();
        })
        .catch(err => {
          this.setError(err);
        });
    }
  };

  setError = err => {
    this.setState(prevState => ({
      ...prevState,
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    }));
  };

  stateReset = () => {
    this.setState(stateObj);
  };

  formModalClose = () => {
    this.stateReset();
    this.props.formModalCloseProp();
  };

  validate = data => {
    const errors = {};

    if (Validator.isEmpty(data.extraCurricularName)) {
      errors.extraCurricularName = 'Name cannot be empty';
    }

    if (Validator.isEmpty(data.category)) {
      errors.category = 'Category type cannot be empty';
    }

    if (Validator.isEmpty(data.description)) {
      errors.description = 'Description type cannot be empty';
    }

    return errors;
  };

  render() {
    const { isOtherActivityModalOpen } = this.props;
    const { data, errors, loading } = this.state;
    const thisData = (
      <Modal size="lg" isOpen={isOtherActivityModalOpen}>
        <form onSubmit={this.handleSubmit}>
          <ModalHeader>ADD ACTIVITY</ModalHeader>
          <ModalBody>
            {errors.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
            <div className="content">
              <div className="container-fluid">
                <Row>
                  <FormGroup className="col-md-12">
                    <Label>
                      Category<sup> *</sup>
                    </Label>
                    <Select
                      onChange={val => this.handleCategoryChange(val)}
                      options={activityCategories}
                      value={activityCategories.find(dt => dt.value === data.category) || null}
                      placeholder="Select..."
                    />
                    {errors?.category && <span className="err-msg">{errors.category}</span>}
                  </FormGroup>
                  <FormGroup className="col-md-12">
                    <Label htmlFor="">
                      Name<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="extraCurricularName"
                      onChange={this.handleChange}
                      value={data.extraCurricularName}
                      placeholder="Enter here..."
                      maxLength="15"
                    />
                    {errors?.extraCurricularName && <span className="err-msg">{errors?.extraCurricularName}</span>}
                  </FormGroup>
                  <FormGroup className="col-md-12">
                    <Label htmlFor="">
                      Description<sup> *</sup>
                    </Label>
                    <Input
                      type="textarea"
                      name="description"
                      onChange={this.handleChange}
                      value={data.description}
                      placeholder="Enter here..."
                      maxLength="1500"
                    />
                    {errors.description && <span className="err-msg">{errors.description}</span>}
                  </FormGroup>
                </Row>
              </div>
            </div>
          </ModalBody>
          <ModalFooter>
            <CustomButton type="submit" disabled={loading} loading={loading} />
            <CustomButton
              className="ml-2"
              type="button"
              color="default"
              disabled={loading}
              onClick={this.formModalClose}
              name="Cancel"
            />
          </ModalFooter>
        </form>
      </Modal>
    );
    return <div>{thisData}</div>;
  }
}

export default OtherActivityFormModal;
