import { useLayoutEffect, useState } from 'react';

// The height that takes a box from where it starts to the bottom of the window, so a list / detail pane fills the screen and
// scrolls inside itself instead of ending short or pushing the page down. `bottomGap` is what stays free below it (a little breathing room: the page footer sits below the fold). Measured again whenever the window is resized.
export const useFillHeight = (ref, bottomGap = 24, minHeight = 360) => {
  const [height, setHeight] = useState(null);
  useLayoutEffect(() => {
    const measure = () => {
      const el = ref.current;
      if (!el) return;
      const next = Math.max(minHeight, Math.round(window.innerHeight - el.getBoundingClientRect().top - bottomGap));
      setHeight(prev => (prev === next ? prev : next));
    };
    measure();
    window.addEventListener('resize', measure);
    return () => window.removeEventListener('resize', measure);
  });
  return height;
};

export default useFillHeight;
