import React, { useEffect, useMemo, useRef, useState } from 'react';
import moment from 'moment';
import { Modal, ModalHeader, ModalBody, ModalFooter } from 'reactstrap';
import SearchIcon from '@material-ui/icons/Search';
import DeleteOutlineIcon from '@material-ui/icons/DeleteOutline';
import colors from 'config/colors';
import CustomButton from 'components/CustomButton';
import { useFillHeight } from 'utils/useFillHeight';
import { useContainWheel } from 'utils/useContainWheel';
import { useSelector } from 'react-redux';
import constants from 'config/constants';
import { markViewedService } from 'actions/admin/contentView';
import { ViewsButton } from './ContentViews';
import RichText from 'views/admin/Common/RichText.jsx';

const NEW_DAYS = 3;
const WIDE_QUERY = '(min-width: 992px)';

// The text of an HTML/rich note without its markup, for the one-line preview. DOMParser builds an inert document, so nothing in
// the note (script, image) runs or loads.
const toPlainText = html => {
  try {
    const text = new DOMParser().parseFromString(html || '', 'text/html').body.textContent || '';
    return text.replace(/\s+/g, ' ').trim();
  } catch (e) {
    return '';
  }
};

const useIsWide = () => {
  const query = typeof window !== 'undefined' && window.matchMedia ? window.matchMedia(WIDE_QUERY) : null;
  const [wide, setWide] = useState(!!query?.matches);
  useEffect(() => {
    if (!query) return undefined;
    const onChange = e => setWide(e.matches);
    query.addListener(onChange);
    return () => query.removeListener(onChange);
  }, [query]);
  return wide;
};

// A calendar-style tile: the day big, the month small.
const DateTile = ({ date, active }) => (
  <div
    style={{
      width: 46,
      flexShrink: 0,
      textAlign: 'center',
      borderRadius: 10,
      padding: '5px 0 4px',
      lineHeight: 1.1,
      background: active ? colors.accent : `${colors.accent}14`,
      color: active ? '#fff' : colors.accent,
    }}>
    <div style={{ fontSize: 18, fontWeight: 'bold' }}>{moment(date).format('DD')}</div>
    <div style={{ fontSize: 10, fontWeight: 'bold', letterSpacing: 0.5, textTransform: 'uppercase' }}>
      {moment(date).format('MMM')}
    </div>
  </div>
);

const Row = ({ id, item, selected, highlighted, onOpen }) => {
  const [hover, setHover] = useState(false);
  const preview = toPlainText(item.content);
  const isNew = moment().diff(moment(item.date), 'days') < NEW_DAYS;
  return (
    <div
      id={id}
      role="button"
      tabIndex={0}
      onClick={onOpen}
      onKeyDown={e => (e.key === 'Enter' || e.key === ' ') && onOpen()}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        display: 'flex',
        alignItems: 'center',
        gap: 12,
        padding: '10px 14px',
        cursor: 'pointer',
        borderBottom: '1px solid #f0eaf5',
        borderLeft: `3px solid ${selected ? colors.accent : 'transparent'}`,
        background: selected || highlighted ? colors.sidebarActiveItemBg : hover ? colors.sidebarBg : colors.white,
        transition: 'background .15s',
      }}>
      <DateTile date={item.date} active={selected} />
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <span
            style={{
              fontWeight: 'bold',
              fontSize: 14,
              color: colors.grey1,
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              whiteSpace: 'nowrap',
            }}>
            {item.title}
          </span>
          {isNew && (
            <span
              style={{
                background: colors.accent,
                color: '#fff',
                borderRadius: 8,
                padding: '0 7px',
                fontSize: 10,
                fontWeight: 'bold',
                flexShrink: 0,
              }}>
              NEW
            </span>
          )}
        </div>
        <div
          style={{
            fontSize: 12.5,
            color: colors.grey3,
            marginTop: 2,
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            whiteSpace: 'nowrap',
          }}>
          {preview || 'Open to view'}
        </div>
      </div>
    </div>
  );
};

// The full note: title, when it was sent, the delete action and the content.
const Detail = ({ item, onDelete, compact, contentType }) => (
  <div>
    <div style={{ display: 'flex', alignItems: 'flex-start', gap: 12 }}>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontSize: compact ? 17 : 20, fontWeight: 'bold', color: colors.grey1, wordBreak: 'break-word' }}>
          {item.title}
        </div>
        <div className="text-muted" style={{ fontSize: 12, marginTop: 2 }}>
          {moment(item.date).format('dddd, DD MMMM YYYY, hh:mm A')} · {moment(item.date).fromNow()}
        </div>
        {!!contentType && (
          <ViewsButton contentType={contentType} contentId={item.id} title={item.title} style={{ marginTop: 8 }} />
        )}
      </div>
      {onDelete && (
        <button
          type="button"
          onClick={onDelete}
          style={{
            border: '1px solid #c62828',
            background: '#fff',
            color: '#c62828',
            borderRadius: 6,
            padding: '4px 12px',
            fontSize: 12,
            fontWeight: 'bold',
            display: 'flex',
            alignItems: 'center',
            gap: 4,
            cursor: 'pointer',
            flexShrink: 0,
          }}>
          <DeleteOutlineIcon style={{ fontSize: 16 }} />
          Delete
        </button>
      )}
    </div>
    <hr style={{ margin: '12px 0' }} />
    <div style={{ fontSize: 14 }}>
      <RichText text={item.content} embed />
    </div>
  </div>
);

// items: [{ id, title, date, content }] newest first. On a wide screen it is a list on the left and the chosen note in full on
// the right; on a narrow one the list is the page and a note opens in a dialog. Rows are grouped by month and can be searched.
const AnnouncementList = ({
  items,
  idPrefix,
  contentType,
  onDelete,
  highlightId,
  emptyText,
  hasMore,
  loadingMore,
  onLoadMore,
}) => {
  const wide = useIsWide();
  const token = useSelector(state => state.auth.loggedUserToken);
  const isTeacher = useSelector(state => state.auth.loggedUserRole) === constants.roles.teacher;
  const listRef = useRef(null);
  const rootRef = useRef(null);
  const paneHeight = useFillHeight(rootRef);
  const detailRef = useRef(null);
  useContainWheel(listRef);
  useContainWheel(detailRef);
  const [query, setQuery] = useState('');
  const [selectedId, setSelectedId] = useState(highlightId || null);
  const [dialogItem, setDialogItem] = useState(null);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return items;
    return items.filter(item => `${item.title} ${toPlainText(item.content)}`.toLowerCase().includes(q));
  }, [items, query]);

  // On a wide screen something is always open: the note a dashboard card pointed at, else the newest one.
  const selected = wide ? filtered.find(item => String(item.id) === String(selectedId)) || filtered[0] : null;

  // The note a teacher is reading counts as seen (the backend records guardians and teachers; an admin's own view is not counted).
  const openId = wide ? selected?.id : dialogItem?.id;
  useEffect(() => {
    if (isTeacher && contentType && openId) {
      markViewedService({ token, contentType, contentId: openId }).catch(() => {});
    }
  }, [openId, contentType, isTeacher]);

  useEffect(() => {
    if (!highlightId) return;
    const el = document.getElementById(`${idPrefix}-${highlightId}`);
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }, [highlightId, idPrefix, items]);

  const groups = [];
  filtered.forEach(item => {
    const label = moment(item.date).format('MMMM YYYY');
    const last = groups[groups.length - 1];
    if (last && last.label === label) last.items.push(item);
    else groups.push({ label, items: [item] });
  });

  const list = (
    <div
      style={{
        background: colors.white,
        border: '1px solid #ece6f2',
        borderRadius: 10,
        overflow: 'hidden',
        boxShadow: '0 1px 3px rgba(0,0,0,0.05)',
        display: 'flex',
        flexDirection: 'column',
        height: wide ? '100%' : 'auto',
      }}>
      <div style={{ padding: 10, borderBottom: '1px solid #f0eaf5' }}>
        <div style={{ position: 'relative' }}>
          <SearchIcon style={{ position: 'absolute', left: 8, top: 7, fontSize: 20, color: colors.grey3 }} />
          <input
            value={query}
            onChange={e => setQuery(e.target.value)}
            placeholder="Search"
            aria-label="Search"
            style={{
              width: '100%',
              padding: '6px 10px 6px 34px',
              border: '1px solid #e2d9ea',
              borderRadius: 18,
              fontSize: 13,
              outline: 'none',
            }}
          />
        </div>
      </div>
      <div ref={listRef} style={{ flex: 1, minHeight: 0, overflowY: 'auto', overscrollBehavior: 'contain' }}>
        {!filtered.length && (
          <div style={{ padding: 24, textAlign: 'center', color: colors.grey3, fontSize: 13 }}>
            {emptyText || 'Nothing matches your search.'}
          </div>
        )}
        {groups.map(group => (
          <div key={group.label}>
            <div
              style={{
                position: 'sticky',
                top: 0,
                zIndex: 1,
                padding: '5px 14px',
                fontSize: 11,
                fontWeight: 'bold',
                letterSpacing: 0.6,
                textTransform: 'uppercase',
                color: colors.accentDark,
                background: colors.sidebarBg,
                borderBottom: '1px solid #f0eaf5',
              }}>
              {group.label}
            </div>
            {group.items.map(item => (
              <Row
                key={item.id}
                id={`${idPrefix}-${item.id}`}
                item={item}
                selected={wide && selected && String(selected.id) === String(item.id)}
                highlighted={!wide && String(item.id) === String(highlightId)}
                onOpen={() => (wide ? setSelectedId(item.id) : setDialogItem(item))}
              />
            ))}
          </div>
        ))}
        {hasMore && (
          <div style={{ padding: 12, textAlign: 'center' }}>
            <button
              type="button"
              disabled={loadingMore}
              onClick={onLoadMore}
              style={{
                border: `1px solid ${colors.accent}`,
                background: '#fff',
                color: colors.accent,
                borderRadius: 18,
                padding: '5px 22px',
                fontSize: 13,
                fontWeight: 'bold',
                cursor: loadingMore ? 'default' : 'pointer',
                opacity: loadingMore ? 0.6 : 1,
              }}>
              {loadingMore ? 'Loading...' : 'View more'}
            </button>
          </div>
        )}
      </div>
    </div>
  );

  if (!wide) {
    return (
      <>
        {list}
        <Modal isOpen={!!dialogItem} toggle={() => setDialogItem(null)} size="lg" scrollable>
          <ModalHeader toggle={() => setDialogItem(null)}>
            <span style={{ fontSize: 15 }}>Details</span>
          </ModalHeader>
          <ModalBody>
            {dialogItem && (
              <Detail
                compact
                contentType={contentType}
                item={dialogItem}
                onDelete={() => {
                  const { id } = dialogItem;
                  setDialogItem(null);
                  onDelete(id);
                }}
              />
            )}
          </ModalBody>
          <ModalFooter>
            <CustomButton color="default" name="Close" onClick={() => setDialogItem(null)} />
          </ModalFooter>
        </Modal>
      </>
    );
  }

  return (
    <div ref={rootRef} style={{ display: 'flex', gap: 16, alignItems: 'stretch', height: paneHeight || undefined }}>
      <div style={{ flex: '1 1 0', minWidth: 0, minHeight: 0 }}>{list}</div>
      <div
        ref={detailRef}
        style={{
          flex: '1 1 0',
          minWidth: 0,
          background: colors.white,
          border: '1px solid #ece6f2',
          borderRadius: 10,
          padding: 20,
          boxShadow: '0 1px 3px rgba(0,0,0,0.05)',
          overflowY: 'auto',
          overscrollBehavior: 'contain',
        }}>
        {selected ? (
          <Detail item={selected} contentType={contentType} onDelete={() => onDelete(selected.id)} />
        ) : (
          <div style={{ textAlign: 'center', color: colors.grey3, padding: 40 }}>Select an item to read it.</div>
        )}
      </div>
    </div>
  );
};

export default AnnouncementList;
