import React from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Input, Label, FormGroup } from 'reactstrap';
import moment from 'moment';
import Validator from 'validator';
import DatePicker from 'react-datepicker';
import Select from 'react-select';
import { activityTypes } from '../ActivityPage';
import CustomButton from '../../../../../components/CustomButton';
import { formResMessage } from 'utils/commonFunc';

const stateObj = {
  data: {
    title: '',
    activityType: '',
    description: '',
    startDateTime: '',
    endDateTime: '',
  },
  errors: {},
  loading: false,
};

class CalendarFormModal extends React.Component {
  state = stateObj;

  componentDidUpdate() {
    if (!this.state.data.activityType) {
      this.handleTypeChange({ value: this.props.activityType });
    }
  }

  handleChange = e => {
    this.setState({
      data: { ...this.state.data, [e.currentTarget.name]: e.currentTarget.value },
    });
  };

  handleDateChange = (name, date) => {
    this.setState({
      data: {
        ...this.state.data,
        [name]: moment(moment(date).format('YYYY-MM-DD HH:mm:ss')).valueOf(),
      },
    });
  };

  handleTypeChange = val => {
    this.setState(prevState => ({
      data: {
        ...prevState.data,
        activityType: val.value,
      },
    }));
    this.props.updateActivity(val.value);
  };

  handleSubmit = e => {
    e.preventDefault();
    const { data } = this.state;
    const errors = this.validate(data);
    this.setState({ errors });
    if (!Object.keys(errors).length) {
      this.setState({ loading: true });
      return this.props
        .saveCalendarActivity(data)
        .then(() => {
          this.stateReset();
          this.props.calendarActivityUpdateSuccess('add', data.activityType);
        })
        .catch(err => this.setError(err));
    }
  };

  setError = err => {
    this.setState(prevState => ({
      ...prevState,
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    }));
  };

  stateReset = () => {
    this.setState(stateObj);
  };

  formModalClose = () => {
    this.stateReset();
    this.props.formModalCloseProp();
  };

  validate = data => {
    const errors = {};

    if (Validator.isEmpty(data.startDateTime.toString().trim())) {
      errors.startDateTime = 'Start Date cannot be empty';
    }

    if (Validator.isEmpty(data.endDateTime.toString().trim())) {
      errors.endDateTime = 'End Date cannot be empty';
    }

    if (Validator.isEmpty(data.title)) {
      errors.title = 'Title cannot be empty';
    }

    if (Validator.isEmpty(data.activityType)) {
      errors.activityType = 'Activity type cannot be empty';
    }

    if (Validator.isEmpty(data.description)) {
      errors.description = 'Description type cannot be empty';
    }

    return errors;
  };

  render() {
    const { isModalOpen, activityType } = this.props;
    const { data, errors, loading } = this.state;
    const thisData = (
      <Modal size="lg" isOpen={isModalOpen}>
        <form onSubmit={this.handleSubmit}>
          <ModalHeader>{data.noticeBoardId ? 'UPDATE CALENDAR ACTIVITY' : 'ADD CALENDAR ACTIVITY'}</ModalHeader>
          <ModalBody>
            {errors.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
            <div className="content">
              <div className="container-fluid">
                <Row>
                  <FormGroup className="col-md-6">
                    <Label htmlFor="">
                      Title<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="title"
                      onChange={this.handleChange}
                      value={data.title}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                    {errors.title && <span className="err-msg">{errors.title}</span>}
                  </FormGroup>
                  <FormGroup className="col-md-6">
                    <Label>
                      Activity type<sup> *</sup>
                    </Label>
                    <Select
                      onChange={val => this.handleTypeChange(val)}
                      options={activityTypes}
                      value={
                        activityTypes.find(dt =>
                          data.activityType ? dt.value === data.activityType : dt.value === activityType
                        ) || null
                      }
                      placeholder="Select..."
                    />
                    {errors.activityType && <span className="err-msg">{errors.activityType}</span>}
                  </FormGroup>
                  <FormGroup className="col-md-6 customDatePickerWidth">
                    <Label htmlFor="">
                      Start Date<sup> *</sup>
                    </Label>
                    <br />
                    <DatePicker
                      className="form-control"
                      selected={data.startDateTime ? new Date(data.startDateTime) : null}
                      onChange={value => this.handleDateChange('startDateTime', value)}
                      dateFormat="dd/MM/yyyy"
                      showMonthDropdown
                      showYearDropdown
                      placeholderText="Select date..."
                      dropdownMode="select"
                    />
                    {errors.startDateTime && <span className="err-msg">{errors.startDateTime}</span>}
                  </FormGroup>
                  <FormGroup className="col-md-6 customDatePickerWidth">
                    <Label htmlFor="">
                      End Date<sup> *</sup>{' '}
                      {!data.startDateTime && (
                        <span style={{ color: 'orange' }}>[Select start date to enable this]</span>
                      )}
                    </Label>
                    <br />
                    <DatePicker
                      className="form-control"
                      selected={data.endDateTime ? new Date(data.endDateTime) : null}
                      onChange={value => this.handleDateChange('endDateTime', value)}
                      dateFormat="dd/MM/yyyy"
                      showMonthDropdown
                      showYearDropdown
                      placeholderText="Select date..."
                      minDate={data.startDateTime ? new Date(data.startDateTime) : null}
                      disabled={!data.startDateTime}
                      dropdownMode="select"
                    />
                    {errors.endDateTime && <span className="err-msg">{errors.endDateTime}</span>}
                  </FormGroup>
                  <FormGroup className="col-md-12">
                    <Label htmlFor="">
                      Description<sup> *</sup>
                    </Label>
                    <Input
                      type="textarea"
                      name="description"
                      onChange={this.handleChange}
                      value={data.description}
                      placeholder="Enter here..."
                      maxLength="1500"
                    />
                    {errors.description && <span className="err-msg">{errors.description}</span>}
                  </FormGroup>
                </Row>
              </div>
            </div>
          </ModalBody>
          <ModalFooter>
            <CustomButton type="submit" disabled={loading} loading={loading} />
            <CustomButton
              className="ml-2"
              type="button"
              color="default"
              disabled={loading}
              onClick={this.formModalClose}
              name="Cancel"
            />
          </ModalFooter>
        </form>
      </Modal>
    );
    return <div>{thisData}</div>;
  }
}

export default CalendarFormModal;
